import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    score = 0
    opp_c = 0
    own_c = 0
    last_opp = history[-1][1]
    for i in range(n):
        own, opp = history[i]
        if own == 'C':
            own_c += 1
        if opp == 'C':
            opp_c += 1
        if own == 'C' and opp == 'C':
            score += 3
        elif own == 'C' and opp == 'D':
            score += 0
        elif own == 'D' and opp == 'C':
            score += 5
        else:
            score += 1
    opp_defects = n - opp_c
    if n < 10:
        if last_opp == 'D':
            return 'D'
        return 'C'
    defect_rate = opp_defects / n
    recent = history[-20:]
    recent_defects = sum(1 for _, o in recent if o == 'D')
    if recent_defects >= 15:
        return 'D'
    if defect_rate > 0.35:
        if rng.random() < 0.7:
            return 'D'
        return 'C'
    if last_opp == 'D':
        recent_opp_def = sum(1 for _, o in history[-5:] if o == 'D')
        if recent_opp_def >= 3:
            return 'D'
        return 'C'
    if defect_rate < 0.05 and n > 30:
        return 'C'
    if n > 80:
        if defect_rate < 0.15:
            return 'C'
        return 'D'
    return 'C'
